private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int limit = bb.limit();
    if (i >= limit) {
        return i;
    }
    int b0 = bb.get(i) & 0xFF;
    // 1-byte sequence
    if (b0 < 0x80) {
        sb.append((char) b0);
        return i + 1;
    }
    // 2-byte sequence
    if ((b0 >> 5) == 0b110) {
        if (i + 1 >= limit) {
            return i;
        }
        int b1 = bb.get(i + 1) & 0x3F;
        int codePoint = ((b0 & 0x1F) << 6) | b1;
        sb.append((char) codePoint);
        return i + 2;
