        int b2 = bb.get(i + 2) & 0x3F;
        int codePoint = ((b0 & 0x0F) << 12) | (b1 << 6) | b2;
        sb.append((char) codePoint);
        return i + 3;
    }
    // 4-byte sequence
    if ((b0 >> 3) == 0b11110) {
