private void enlarge(final int size){
    // If the internal buffer is null, create a new one with the requested size
    if (data == null) {
        data = new byte[size];
        return;
    }
    // Compute a new capacity that can accommodate the additional bytes.
    // Prefer doubling the current capacity to keep amortized O(1) growth.
    int newCapacity = Math.max(data.length + size, data.length * 2);
    // Allocate the new buffer and copy existing data into it.
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, data.length);
    // Replace the old buffer with the enlarged one.
    data = newData;
