public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] args = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    Map<TypeVariable<?>, Type> typeVarAssigns = new HashMap<>();
    buildTypeVarAssigns(targetType, typeVarAssigns);
    for (int i = 0; i < args.length; i++) {
        Type arg = args[i];
        if (arg instanceof Class<?>) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable<?>) {
            Type resolved = resolveTypeVariable((TypeVariable<?>) arg, typeVarAssigns);
            if (resolved instanceof Class<?>) {
                result[i] = (Class<?>) resolved;
            } else {
                return null;
            }
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                result[i] = (Class<?>) raw;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

private static void buildTypeVarAssigns(Class<?> clazz, Map<TypeVariable<?>, Type> map) {
    if (clazz == null || clazz == Object.class) {
        return;
    }
    // Process superclass
    Type genericSuper = clazz.getGenericSuperclass();
    if (genericSuper instanceof ParameterizedType) {
        ParameterizedType pSuper = (ParameterizedType) genericSuper;
        Class<?> superClass = (Class<?>) pSuper.getRawType();
        TypeVariable<?>[] vars = superClass.getTypeParameters();
        Type[] args = pSuper.getActualTypeArguments();
        for (int i = 0; i < vars.length; i++) {
            map.put(vars[i], args[i]);
        }
        buildTypeVarAssigns(superClass, map);
    } else if (genericSuper instanceof Class<?>) {
        buildTypeVarAssigns((Class<?>) genericSuper, map);
    }
    // Process interfaces
    for (Type iface : clazz.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pIface = (ParameterizedType) iface;
            Class<?> ifaceClass = (Class<?>) pIface.getRawType();
            TypeVariable<?>[] vars = ifaceClass.getTypeParameters();
            Type[] args = pIface.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            buildTypeVarAssigns(ifaceClass, map);
        } else if (iface instanceof Class<?>) {
            buildTypeVarAssigns((Class<?>) iface, map);
        }
    }
}

private static Type resolveTypeVariable(TypeVariable<?> var, Map<TypeVariable<?>, Type> map) {
    Type t = map.get(var);
    if (t == null) {
        return var;
    }
    if (t instanceof TypeVariable<?>) {
        return resolveTypeVariable((TypeVariable<?>) t, map);
    }
    return t;
