public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the specified table
    Mappings current = getMapping(tableName);
    if (current == null) {
        return new Mappings();
    }

    // Get the property maps from both current and input mappings
    Map<String, Object> currentProps = current.getProperties();
    Map<String, Object> inputProps = mappings != null ? mappings.getProperties() : null;

    // Prepare a map to hold fields that exist in current but not in input
    Map<String, Object> diffProps = new LinkedHashMap<>();

    if (currentProps != null) {
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();

            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(field)) {
                continue;
            }

            // If the field is not present in the input mapping, add it to the diff
            if (inputProps == null || !inputProps.containsKey(field)) {
                diffProps.put(field, entry.getValue());
            }
        }
    }

    // Build the resulting diff mapping
    Mappings diff = new Mappings();
    diff.setProperties(diffProps);
    return diff;
