public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/' and ignore empty parts (which can occur if path ends with '/')
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; ignore if it somehow fails
            }
        }
        // PathSegmentImpl constructor expects the decoded path
        segments.add(new PathSegmentImpl(decoded, null));
    }
    return segments;
