protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }

    // Null values are allowed and simply return null
    if (value == null) {
        return null;
    }

    // If already a Character, return it directly
    if (value instanceof Character) {
        return value;
    }

    // Convert from String: must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException(
                "Cannot convert String to Character: length must be 1");
        }
    }

    // Convert from Number: cast to int and then to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new IllegalArgumentException(
                "Number value out of char range: " + intVal);
        }
        return (char) intVal;
    }

    // Unsupported source type
    throw new IllegalArgumentException(
        "Cannot convert type " + value.getClass().getName() + " to Character");
