public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= str.length()) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: \\u" + hex);
                    }
                    i += 5;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int oct = 0;
                        int count = 0;
                        while (j < str.length() && count < 3 && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            oct = (oct << 3) + (str.charAt(j) - '0');
                            j++;
                            count++;
                        }
                        sb.append((char) oct);
                        i = j - 1;
                    } else {
                        sb.append(next);
                        i++;
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
