private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // If the start node is the stop node, return immediately
    if (start == stop) {
        return circ;
    }

    // Traverse the outer face until we find a node that satisfies the predicate
    // or until we reach the stop node.
    while (true) {
        Node current = circ.getNode();

        // Check the predicate
        if (predicate.test(current)) {
            return circ;
        }

        // Stop if we have reached the stop node
        if (current == stop) {
            return circ;
        }

        // Move to the next or previous node based on the direction
        if (dir > 0) {
            circ = circ.next();
        } else {
            circ = circ.prev();
        }
    }
