private String unescapeId(String input){
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'x':
                    if (i + 3 < len) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 3;
                        } catch (NumberFormatException e) {
                            sb.append('x');
                            i++;
                        }
                    } else {
                        sb.append('x');
                        i++;
                    }
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('u');
                            i++;
                        }
                    } else {
                        sb.append('u');
                        i++;
                    }
                    break;
                default:
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
