    // If the minLabel bucket is already the zero bucket, nothing to move
    if (minLabel == 0) {
        return;
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    // Use a copy to avoid ConcurrentModificationException
    for (Integer v : new HashSet<>(minBucket)) {
        minBucket.remove(v);
        zeroBucket.add(v);
