    if (path == null) {
        return null;
    }
    int slash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int dot = path.lastIndexOf('.');
    // No dot, or dot is before the last slash (i.e., part of a directory name)
    if (dot == -1 || dot <= slash) {
        return null;
    }
    // Dot is the first character of the filename (e.g., ".bashrc") or the last character (e.g., "file.")
