private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.size == 0) {
        return;
    }
    // Detach the source list's nodes from any previous links
    if (list.head != null) {
        list.head.prev = null;
    }
    if (list.tail != null) {
        list.tail.next = null;
    }
    // Append the source list to this list
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.size += list.size;
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
