private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
