private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort((a, b) -> ((Comparable<K>)a).compareTo(b));
    // For each key, find the index of the first element greater than the key
    for (K key : keys) {
        int idx = 0;
        while (idx < sorted.size() && ((Comparable<K>)sorted.get(idx)).compareTo(key) <= 0) {
            idx++;
        }
        bounds.add(idx);
    }
    return bounds;
