public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Split the base path into components
    String[] baseParts = path.split("/");
    int baseLen = baseParts.length;
    // If the base path does not end with a slash, assume the last component is a file and drop it
    if (!path.endsWith("/")) {
        baseLen = Math.max(0, baseLen - 1);
    }
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (int i = 0; i < baseLen; i++) {
        String part = baseParts[i];
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }
    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    // Preserve leading slash if the original path was absolute
    if (path.startsWith("/")) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    return result.toString();
}<|return|>

